// ############################################################
// PART 2: EMISSIONS HEAT MAP (globe, charts, dialog)
// ############################################################
// ============================================================
// CarboMetrics - interactive emissions heat map
//
//   * HeatModel          : data + aggregation (continent / region / country)
//   * HeatGlobeView      : 3D orthographic globe, drag / zoom / hover / click
//   * TrendChart         : small time-series chart for the selection
//   * LegendBar          : colour legend that follows the active scale
//   * EmissionsHeatmapDialog : the window that ties everything together
//
// Header-only and free of Q_OBJECT / signals, so it needs no moc step:
// just #include it. Works with Qt 5.12+ and Qt 6.
// ============================================================

#include <QApplication>
#include <QDialog>
#include <QWidget>
#include <QFrame>
#include <QLabel>
#include <QPushButton>
#include <QComboBox>
#include <QSlider>
#include <QScrollArea>
#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QPainter>
#include <QPainterPath>
#include <QPolygonF>
#include <QRadialGradient>
#include <QLinearGradient>
#include <QMouseEvent>
#include <QWheelEvent>
#include <QTimer>
#include <QPixmap>
