    header->setHighlightSections(false);

    reportsTable->setColumnHidden(0, true);

    // Buttons

    QPushButton *deleteButton = new QPushButton("Delete Selected Record");
    deleteButton->setObjectName("dangerButton");

    QPushButton *refreshButton = new QPushButton("Refresh Reports");
    refreshButton->setObjectName("primaryButton");

