    layout->addLayout(buttonRow);

    connect(deleteButton, &QPushButton::clicked,
            this, &MainWindow::deleteSelectedRecord);

    connect(refreshButton, &QPushButton::clicked,
            this, &MainWindow::refreshReportsTable);

    refreshReportsTable();
