// ============================================================
// MODULE 5: REFRESH REPORTS TABLE
// ============================================================

void MainWindow::refreshReportsTable()
{
    if (reportsTable == nullptr) {
        return;
    }

    if (!databaseManager.openDatabase()) {
        QMessageBox::critical(
            this,
            "Database Error",
            "Could not open the database:\n" +
                databaseManager.lastError()
            );
        return;
    }

    if (!databaseManager.createTables()) {
        QMessageBox::critical(
            this,
            "Database Error",
            "Could not prepare the reports table:\n" +
                databaseManager.lastError()
            );
        return;
    }

    const QVector<EmissionRecord> records =
        databaseManager.getAllRecords();

    // clearSpans() matters: the empty-state row uses a span, and a
    // leftover span would break row 0 once real data is inserted.
    reportsTable->clearSpans();
    reportsTable->clearContents();
    reportsTable->setRowCount(0);

    const Qt::Alignment left = Qt::AlignLeft | Qt::AlignVCenter;
    const Qt::Alignment right = Qt::AlignRight | Qt::AlignVCenter;

    double sumTransport = 0.0;
    double sumElectricity = 0.0;
    double sumFood = 0.0;
    double sumTotal = 0.0;

    for (const EmissionRecord &record : records) {
        const int row = reportsTable->rowCount();

        reportsTable->insertRow(row);

        sumTransport += record.transportEmissions;
        sumElectricity += record.electricityEmissions;
        sumFood += record.foodEmissions;
        sumTotal += record.totalEmissions;

        reportsTable->setItem(row, 0, makeItem(QString::number(record.id)));

        const QDateTime dateTime = QDateTime::fromString(
            record.recordedAt, Qt::ISODate);

        const QString formattedDate = dateTime.isValid()
                                          ? dateTime.toString("dd MMM yyyy, hh:mm AP")
                                          : record.recordedAt;

        reportsTable->setItem(row, 1, makeItem(formattedDate, left));
        reportsTable->setItem(row, 2, makeItem(record.userName, left));

        const QString transportText = record.transportType.isEmpty()
                                          ? QString("%1 kg").arg(record.transportEmissions, 0, 'f', 2)
                                          : QString("%1  -  %2 kg")
                                                .arg(record.transportType)
                                                .arg(record.transportEmissions, 0, 'f', 2);

        reportsTable->setItem(row, 3, makeItem(transportText, left));

        reportsTable->setItem(row, 4, makeItem(
                                          QString("%1 kg").arg(record.electricityEmissions, 0, 'f', 2), right));

        reportsTable->setItem(row, 5, makeItem(
                                          QString("%1 kg").arg(record.foodEmissions, 0, 'f', 2), right));

        QTableWidgetItem *totalItem = makeItem(
            QString("%1 kg").arg(record.totalEmissions, 0, 'f', 2), right);
        QFont bold = totalItem->font();
        bold.setBold(true);
        totalItem->setFont(bold);
        reportsTable->setItem(row, 6, totalItem);

        QTableWidgetItem *categoryItem = makeItem(
            QString::fromUtf8("\xE2\x97\x8F ") + record.footprintCategory,
            Qt::AlignCenter);
        categoryItem->setForeground(
            QColor(Theme::categoryColor(record.footprintCategory)));
        categoryItem->setFont(bold);
        reportsTable->setItem(row, 7, categoryItem);
    }

    if (records.isEmpty()) {
        reportsTable->setRowCount(1);

        QTableWidgetItem *emptyItem = makeItem(
            "No saved reports yet. Calculate your emissions "
            "to create your first report.",
            Qt::AlignCenter);

        reportsTable->setItem(0, 1, emptyItem);
        reportsTable->setSpan(0, 1, 1, 7);
    }

    // Charts and summary

    if (reportsDonut != nullptr) {
        reportsDonut->setData(sumTransport, sumElectricity, sumFood);
    }

    if (reportsTrend != nullptr) {
        QVector<double> values;
        QStringList labels;

        // Records are newest-first; show the latest 8, oldest on the left.
        const int count = qMin(8, static_cast<int>(records.size()));

        for (int i = count - 1; i >= 0; --i) {
            values.append(records[i].totalEmissions);

            const QDateTime dt = QDateTime::fromString(
                records[i].recordedAt, Qt::ISODate);

            labels.append(dt.isValid()
                              ? dt.toString("dd MMM\nhh:mm")
                              : QString::number(records[i].id));
        }

        reportsTrend->setData(values, labels);
    }

    if (reportsSummary != nullptr) {
        if (records.isEmpty()) {
            reportsSummary->setText(
                "View your saved carbon emission calculations and track "
                "your environmental footprint over time.");
        }
        else {
            reportsSummary->setText(
                QString("%1 saved report%2  |  Average: %3 kg CO2e per report")
                    .arg(records.size())
                    .arg(records.size() == 1 ? "" : "s")
                    .arg(sumTotal / records.size(), 0, 'f', 2));
        }
    }
}

// ============================================================
// MODULE 5: DELETE SELECTED RECORD
// ============================================================

void MainWindow::deleteSelectedRecord()
{
    if (reportsTable == nullptr) {
        return;
    }

    const int row = reportsTable->currentRow();

    if (row < 0) {
        QMessageBox::warning(
            this,
            "No Record Selected",
            "Please select a report to delete."
            );
        return;
    }

    QTableWidgetItem *idItem = reportsTable->item(row, 0);

    if (idItem == nullptr) {
        QMessageBox::warning(
            this,
            "Invalid Selection",
            "Please select a valid saved report."
            );
        return;
    }

    bool validId = false;

    const int recordId = idItem->text().toInt(&validId);

    if (!validId || recordId <= 0) {
        QMessageBox::warning(
            this,
            "Invalid Selection",
            "The selected row is not a saved report."
            );
        return;
    }

    const QMessageBox::StandardButton answer =
        QMessageBox::question(
            this,
            "Confirm Deletion",
            "Are you sure you want to delete this report?",
            QMessageBox::Yes | QMessageBox::No,
            QMessageBox::No
            );

    if (answer != QMessageBox::Yes) {
        return;
    }

    if (!databaseManager.deleteRecord(recordId)) {
        QMessageBox::critical(
            this,
            "Deletion Failed",
            "Could not delete the selected report:\n" +
                databaseManager.lastError()
            );
        return;
    }

    // The table and charts update immediately; no extra popup needed.
    refreshReportsTable();
}

// ============================================================
// CALCULATE EMISSIONS
// ============================================================

void MainWindow::calculateEmissions()
{
    // STEP 1: Validate the user's name.

    const QString name = nameInput->text().trimmed();

    if (name.isEmpty()) {
        QMessageBox::warning(
            this,
            "Missing Information",
            "Please enter your name."
            );

        nameInput->setFocus();
        return;
    }

    // STEP 2: Read the input values.

    const QString distanceText = distanceInput->text().trimmed();
    const QString electricityText = electricityInput->text().trimmed();
    const QString servingsText = foodServingsInput->text().trimmed();

    bool distanceOk = distanceText.isEmpty();
    bool electricityOk = electricityText.isEmpty();
    bool servingsOk = servingsText.isEmpty();

    const double distance = distanceText.isEmpty()
                                ? 0.0
                                : distanceText.toDouble(&distanceOk);

    const double electricity = electricityText.isEmpty()
                                   ? 0.0
                                   : electricityText.toDouble(&electricityOk);

    const int servings = servingsText.isEmpty()
                             ? 0
                             : servingsText.toInt(&servingsOk);

    // STEP 3: Validate transportation distance.

    if (!distanceOk || distance < 0.0 || distance > 100000.0) {
        QMessageBox::warning(
            this,
            "Invalid Distance",
            "Enter a distance between 0 and 100000 km."
            );

        distanceInput->setFocus();
        return;
    }

    // STEP 4: Validate electricity consumption.

    if (!electricityOk ||
        electricity < 0.0 ||
        electricity > 100000.0) {

        QMessageBox::warning(
            this,
            "Invalid Electricity Usage",
            "Enter electricity usage between 0 and 100000 kWh."
            );

        electricityInput->setFocus();
        return;
    }

    // STEP 5: Validate food servings.

    if (!servingsOk || servings < 0 || servings > 1000) {
        QMessageBox::warning(
            this,
            "Invalid Servings",
            "Enter a number of servings between 0 and 1000."
            );

        foodServingsInput->setFocus();
        return;
    }

    // STEP 6: Start a fresh calculation.

    analyzer.clearActivities();

    int activityCount = 0;

    double transportEmissions = 0.0;
    double electricityEmissions = 0.0;
    double foodEmissions = 0.0;

    // These are illustrative development factors, not verified
    // universal scientific emission factors.

    // STEP 7: Calculate transportation emissions.

    if (distance > 0.0) {
        const QString selectedTransport = transportType->currentText();

        double transportFactor = 0.0;

        if (selectedTransport == "Car") {
            transportFactor = 0.15;
        }
        else if (selectedTransport == "Motorcycle") {
            transportFactor = 0.10;
        }
        else if (selectedTransport == "Bus") {
            transportFactor = 0.08;
        }
        else if (selectedTransport == "Train") {
            transportFactor = 0.04;
        }
        else if (selectedTransport == "Electric Vehicle") {
            transportFactor = 0.05;
        }

        // Bicycle and Walking use a factor of zero in this model.

        analyzer.addActivity(
            std::make_unique<TransportActivity>(
                selectedTransport,
                distance,
                transportFactor
                )
            );

        transportEmissions = distance * transportFactor;

        ++activityCount;
    }

    // STEP 8: Calculate electricity emissions.

    if (electricity > 0.0) {
        constexpr double electricityFactor = 0.70;

        analyzer.addActivity(
            std::make_unique<ElectricityActivity>(
                "Electricity Consumption",
                electricity,
                electricityFactor
                )
            );

        electricityEmissions = electricity * electricityFactor;

        ++activityCount;
    }

    // STEP 9: Calculate food emissions.

    if (servings > 0) {
        const QString selectedDiet = foodType->currentText();

        double foodFactor = 0.0;

        if (selectedDiet == "Plant-based") {
            foodFactor = 0.50;
        }
        else if (selectedDiet == "Vegetarian") {
            foodFactor = 0.80;
        }
        else if (selectedDiet == "Mixed Diet") {
            foodFactor = 1.50;
        }
        else if (selectedDiet == "Meat-heavy") {
            foodFactor = 2.50;
        }

        analyzer.addActivity(
            std::make_unique<FoodActivity>(
                "Food Consumption",
                selectedDiet,
                servings,
                foodFactor
                )
            );

        foodEmissions = servings * foodFactor;

        ++activityCount;
    }

    // STEP 10: Module 2 calculates total emissions.

    const double totalEmissions = analyzer.calculateTotalEmissions();

    // ========================================================
    // MODULE 4: SMART ADVISORY SYSTEM
    // ========================================================

    const QStringList recommendations =
        advisorySystem.generateRecommendations(
            transportEmissions,
            electricityEmissions,
            foodEmissions
            );

    if (suggestionsLabel != nullptr) {
        QStringList bullets;

        for (const QString &recommendation : recommendations) {
            bullets.append(QString::fromUtf8("\xE2\x80\xA2  ") + recommendation);
        }

        suggestionsLabel->setText(bullets.join("\n\n"));
    }

    // ========================================================
    // MODULE 3: CARBON FOOTPRINT ANALYSIS
    // ========================================================

    const FootprintAnalyzer::Category category =
        footprintAnalyzer.classifyFootprint(totalEmissions);

    const QString categoryName =
        footprintAnalyzer.getCategoryName(category);

    const QString analysis =
        footprintAnalyzer.getAnalysis(totalEmissions);

    // ========================================================
    // MODULE 5: SAVE THE CALCULATION
    // ========================================================

    EmissionRecord record;

    record.userName = name;
    record.recordedAt = QDateTime::currentDateTime().toString(Qt::ISODate);

    record.transportType = transportType->currentText();
    record.distance = distance;
    record.transportEmissions = transportEmissions;

    record.electricity = electricity;
    record.electricityEmissions = electricityEmissions;

    record.foodCategory = foodType->currentText();
    record.servings = servings;
    record.foodEmissions = foodEmissions;

    record.totalEmissions = totalEmissions;
    record.footprintCategory = categoryName;

    bool recordSaved = false;
    QString saveError;

    if (!databaseManager.openDatabase()) {
        saveError = databaseManager.lastError();
    }
    else if (!databaseManager.createTables()) {
        saveError = databaseManager.lastError();
    }
    else if (!databaseManager.saveRecord(record)) {
        saveError = databaseManager.lastError();
    }
    else {
        recordSaved = true;
    }

    if (recordSaved) {
        refreshReportsTable();
    }

    // ========================================================
    // UPDATE DASHBOARD
    // ========================================================

    if (activitiesValue != nullptr) {
        activitiesValue->setText(QString::number(activityCount));
    }

    // Share the latest daily footprint with the global heat map dialog,
    // so it can compare you with the average person in each country.
    QApplication::instance()->setProperty("carboLastDailyKg", totalEmissions);

    if (emissionsValue != nullptr) {
        emissionsValue->setText(
            QString("%1 kg CO2e").arg(totalEmissions, 0, 'f', 2));
    }

    if (dashboardDonut != nullptr) {
        dashboardDonut->setData(
            transportEmissions, electricityEmissions, foodEmissions);
    }

    // ========================================================
    // UPDATE STATUS MESSAGE (one short line)
    // ========================================================

    statusLabel->setText(
        QString("Last result: %1 kg CO2e  |  %2 footprint  |  %3")
            .arg(totalEmissions, 0, 'f', 2)
            .arg(categoryName)
            .arg(recordSaved ? "Report saved" : "Report NOT saved"));

    // ========================================================
    // DISPLAY RESULTS
    // ========================================================

    ResultData data;

    data.userName = name;
    data.transportType = transportType->currentText();
    data.dietCategory = foodType->currentText();
    data.category = categoryName;
    data.analysis = analysis;
    data.recommendations = recommendations;

    data.distance = distance;
    data.electricity = electricity;
    data.servings = servings;
    data.activityCount = activityCount;

    data.transportEmissions = transportEmissions;
    data.electricityEmissions = electricityEmissions;
    data.foodEmissions = foodEmissions;
    data.total = totalEmissions;
    data.saved = recordSaved;

    ResultDialog dialog(data, this);
    dialog.exec();

    if (!recordSaved) {
        QMessageBox::warning(
            this,
            "Report Not Saved",
            "The calculation completed, but the report could not "
            "be saved:\n" + saveError
            );
    }
}

// ============================================================
// CLEAR FORM
// ============================================================

void MainWindow::clearForm()
{
    nameInput->clear();
    distanceInput->clear();
    electricityInput->clear();
    foodServingsInput->clear();

    transportType->setCurrentIndex(0);
    foodType->setCurrentIndex(0);

    statusLabel->clear();

    if (suggestionsLabel != nullptr) {
        suggestionsLabel->setText(
            "Calculate your emissions first to receive personalized suggestions."
            );
    }

    nameInput->setFocus();
}

